interface ProductsLoadMoreEvent extends CustomEvent {
  detail: {
    sections: Record<string, string>;
  };
}

class LoadMore extends HTMLElement {
  private unsubscribe: (() => void) | undefined;

  constructor() {
    super();
  }

  connectedCallback(): void {
    const sectionId = this.getAttribute("data-section-id");

    if (!sectionId) {
      return;
    }

    this.setupLoadMoreHandler();
  }

  disconnectedCallback(): void {
    this.unsubscribe?.();
  }

  private setupLoadMoreHandler(): void {
    const loadMoreButton = this.querySelector<HTMLAnchorElement>("a");

    if (!loadMoreButton) {
      return;
    }

    loadMoreButton.addEventListener("click", async (event) => {
      event.preventDefault();

      const href = loadMoreButton.href;
      if (!href) return;

      const sectionId = this.getAttribute("data-section-id");
      if (!sectionId) return;

      // Add loading state
      loadMoreButton.classList.add("is-loading");
      loadMoreButton.setAttribute("disabled", "true");

      try {
        const url = new URL(href);
        url.searchParams.set("sections", sectionId);

        const response = await fetch(url.toString());
        const sections = await response.json();

        // Dispatch event for the product grid to handle
        document.dispatchEvent(
          new CustomEvent("products:load-more", {
            detail: { sections },
          }) as ProductsLoadMoreEvent,
        );
      } catch (error) {
        console.error("Failed to load more products:", error);

        // Remove loading state on error
        loadMoreButton.classList.remove("is-loading");
        loadMoreButton.removeAttribute("disabled");
      }
    });
  }
}

if (!customElements.get("uwp-load-more")) {
  customElements.define("uwp-load-more", LoadMore);
}

export default LoadMore;
